-- Top 20 LLD + top 20 HLD interview problems (adds 12 LLD + 14 HLD, sets a learning order).

INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('snake-ladder', 'Snake and Ladder', 'Easy', 'Board game with players, dice, snakes and ladders.', 'Design the game Snake and Ladder.

Two or more players take turns rolling a dice and moving on a 100-cell board. Snakes send you down, ladders take you up, and the first player to reach the last cell wins. Clarify the rules with the interviewer.', '{"requirements": ["Number of players, board size, number of dice", "What happens on exact landing vs overshooting 100", "Snake head/tail and ladder start/end rules; no cycles", "Turn order, winner detection, game end", "Out of scope: UI, online multiplayer unless asked"], "entities": ["Game, Board, Cell or position map, Snake, Ladder, Player, Dice", "Board holds snakes and ladders (or a jump map from cell to cell)", "Game holds players (queue) and board"], "uml": ["Dice behind an interface so a crooked/multi dice can be swapped (Strategy)", "Snakes and ladders modelled uniformly as jumps/BoardEntity", "Game loop separated from board rules", "Consistent with entities; correct multiplicities"], "code": ["roll -> move -> apply snake/ladder -> check win, in a clean loop", "Turn rotation with a queue", "Overshoot rule handled", "No god class; board validation (no snake at 100, no overlaps)"], "twist": ["Add a rule: rolling three sixes in a row skips your turn", "Support two dice and a ''crooked'' dice that only rolls even numbers", "Allow an undo of the last move", "Make the board size and entities configurable from a file"]}', 1, 3, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('chess', 'Chess', 'Hard', 'Pieces, moves, check and checkmate on an 8x8 board.', 'Design a chess game for two players.

Players take turns moving pieces on an 8x8 board. Each piece moves differently, illegal moves are rejected, and the game ends in checkmate, stalemate or resignation. Agree on scope with the interviewer.', '{"requirements": ["Two players, turn order, colours", "Move validation per piece type; special moves (castling, en passant, promotion) in or out of scope", "Check, checkmate, stalemate, resignation", "Move history", "Out of scope: AI opponent, clocks unless asked"], "entities": ["Game, Board, Cell/Square, Piece (abstract) with King, Queen, Rook, Bishop, Knight, Pawn", "Player, Move (from, to, piece, captured)", "Board has 64 cells; cell has optional piece"], "uml": ["Piece hierarchy with polymorphic canMove/possibleMoves", "Move objects (Command) enabling undo/history", "Separate rule/validation component for check detection", "Diagram consistent with entities"], "code": ["makeMove validates turn, piece rules, path blocking and own-king safety", "Check detection reusing piece move generation", "Clean polymorphism, no giant switch on piece type", "Game status transitions handled"], "twist": ["Add undo/redo of moves", "Add a chess clock per player", "Add a variant: Chess960 starting positions", "Let a spectator replay any finished game move by move"]}', 1, 17, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('library-management', 'Library Management', 'Easy', 'Books, members, borrowing, returns and fines.', 'Design a library management system.

Members search for books, borrow copies, return them and pay fines when late. Librarians add books and manage members. Decide the scope with the interviewer.', '{"requirements": ["Search by title/author/subject", "Book vs physical copy (BookItem) distinction", "Borrow limits per member, due dates, fines", "Reservations/holds in or out of scope", "Roles: member vs librarian"], "entities": ["Library, Book (metadata), BookItem (copy with barcode/status), Member, Librarian, Loan/Lending, Fine", "Search catalogue/index", "Book has many BookItems; Member has many Loans"], "uml": ["Book vs BookItem separation", "Fine calculation as a Strategy", "Notification on due date (Observer) if justified", "Search behind an interface"], "code": ["checkout(member, bookItem) enforces limit and availability", "return() computes fine and frees the copy", "Status enum for BookItem", "Code matches UML"], "twist": ["Add reservations: notify the next member when a copy is returned", "Different borrow limits and fine rules for students vs faculty", "Two members try to borrow the last copy at the same time", "Add e-books with simultaneous-borrow limits"]}', 1, 6, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('atm', 'ATM Machine', 'Medium', 'Card, PIN, withdrawals and cash dispensing with states.', 'Design an ATM.

A user inserts a card, enters a PIN, and can check balance, withdraw or deposit cash. The machine has limited notes of each denomination. Clarify the details first.', '{"requirements": ["Card + PIN authentication, attempts limit", "Operations: balance, withdraw, deposit, mini statement", "Denominations and dispensing logic", "Talks to a bank service; handles failures", "Daily withdrawal limit"], "entities": ["ATM, CardReader, Keypad, Screen, CashDispenser, Card, Account, BankService, Transaction types", "ATM states: Idle, CardInserted, Authenticated, etc."], "uml": ["State pattern for ATM flow", "Chain of Responsibility for note dispensing (2000 -> 500 -> 100)", "Transactions as a hierarchy or Command", "BankService behind an interface"], "code": ["Withdraw checks balance, daily limit and cash availability before dispensing", "Dispense algorithm that fails cleanly if exact amount impossible", "State transitions enforced", "Rollback if dispense fails after debit"], "twist": ["Cash dispensed but the bank call times out: what now?", "Add UPI cardless withdrawal", "Machine runs out of 500 notes mid-day", "Add a maintenance mode for technicians"]}', 1, 10, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('hotel-booking', 'Hotel Booking', 'Medium', 'Rooms, search by dates, bookings and cancellations.', 'Design a hotel booking system for one hotel chain.

Guests search rooms by dates and type, book, pay and cancel. The hotel manages room inventory and pricing. Agree on scope first.', '{"requirements": ["Search by date range, room type, guests", "Book, pay, cancel with policy", "Room types and pricing (seasonal)", "No double booking for overlapping dates", "Check-in/check-out"], "entities": ["Hotel, Room (type, number), RoomType, Booking (dates, status), Guest, Payment, Invoice", "Availability per room per date"], "uml": ["Pricing as Strategy (seasonal/weekend)", "Booking state machine (reserved, confirmed, cancelled, checked-in)", "Availability check isolated", "Diagram consistent with entities"], "code": ["Overlap check for date ranges", "Atomic book that prevents double booking", "Cancellation with refund policy", "Clean separation of payment"], "twist": ["Two guests book the last deluxe room for overlapping dates at the same time", "Add a loyalty programme with points", "Overbooking allowed up to 5% with compensation rules", "Add room upgrades at check-in"]}', 1, 13, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('logging-framework', 'Logging Framework', 'Easy', 'Log levels, multiple outputs, formatting, thread safety.', 'Design a logging library like log4j or Python''s logging.

Applications log messages at different levels; messages can go to the console, files or a remote service, with configurable formats. Clarify requirements first.', '{"requirements": ["Levels (DEBUG..FATAL) and filtering by level", "Multiple appenders/sinks: console, file, remote", "Configurable format", "Thread safety; performance (async)", "Per-module loggers"], "entities": ["Logger, LogLevel, LogMessage/Record, Appender (interface) with ConsoleAppender, FileAppender", "Formatter, LoggerFactory/Manager, Configuration"], "uml": ["Singleton or factory for loggers", "Appenders as Strategy/Observer", "Chain of Responsibility for level handling if used", "Formatter separated"], "code": ["log(level, msg) filters then fans out to appenders", "Thread-safe writes", "Formatter applied consistently", "Easy to add a new appender"], "twist": ["Add async logging without losing messages on crash", "Rotate log files at 100 MB", "Mask PII like phone numbers in messages", "Change log level at runtime without restart"]}', 1, 5, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('food-delivery', 'Food Delivery (Zomato / Swiggy)', 'Hard', 'Restaurants, menus, cart, orders and delivery assignment.', 'Design the core of a food delivery app like Zomato or Swiggy.

Customers browse restaurants, add items to a cart and place orders. Restaurants accept and prepare orders; delivery partners pick them up. Scope it with the interviewer.', '{"requirements": ["Browse restaurants/menus, cart from a single restaurant", "Place order, pay, track status", "Restaurant accepts/rejects, prep time", "Delivery partner assignment and tracking", "Ratings in or out of scope"], "entities": ["Customer, Restaurant, Menu, MenuItem, Cart, CartItem, Order, OrderItem, Payment, DeliveryPartner, Address", "Order status enum"], "uml": ["Order state machine", "Delivery assignment strategy (nearest, least busy)", "Observer for order status updates", "Payment behind interface"], "code": ["placeOrder validates cart and creates order atomically", "assignPartner via strategy", "Status transitions enforced", "No god OrderService"], "twist": ["Restaurant cancels after the partner is already on the way", "Add group orders from multiple users", "Surge delivery fee during rain", "Support scheduled orders for later"]}', 1, 19, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('cab-booking', 'Cab Booking (Uber / Ola)', 'Hard', 'Riders, drivers, matching, trips and fares.', 'Design the core classes of a cab booking app like Uber or Ola.

A rider requests a ride, nearby drivers are matched, a driver accepts and the trip runs until payment. Agree on scope first.', '{"requirements": ["Request ride with pickup/drop, vehicle types", "Match nearby available driver; accept/reject", "Trip lifecycle and fare calculation", "Ratings, cancellations", "Out of scope: maps/routing internals"], "entities": ["Rider, Driver, Vehicle, Location, RideRequest, Trip, Fare/Pricing, Payment", "Driver status and trip status enums"], "uml": ["Matching as Strategy", "Pricing as Strategy (base + per km + surge)", "Trip state machine", "Observer for notifications"], "code": ["requestRide finds candidates and offers to drivers", "Driver accept is atomic (no double assignment)", "Fare computed via strategy at trip end", "Cancellation rules"], "twist": ["Two riders get matched to the same driver at the same moment", "Add shared rides (pool)", "Driver rejects 3 times: what happens?", "Add scheduled rides for airport pickups"]}', 1, 18, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('pub-sub', 'Pub-Sub / Message Queue', 'Medium', 'Topics, publishers, subscribers and delivery guarantees in memory.', 'Design an in-memory publish-subscribe system, a tiny Kafka.

Publishers send messages to topics; subscribers receive messages from topics they follow. Discuss ordering and delivery guarantees.', '{"requirements": ["Create topics, publish, subscribe/unsubscribe", "Ordering per topic; at-least-once vs at-most-once", "Push vs pull consumers", "Concurrency: many publishers/consumers", "Retention/offsets in or out of scope"], "entities": ["Broker/MessageQueue, Topic, Message, Publisher, Subscriber (interface), Consumer offset", "Topic has many messages and subscribers"], "uml": ["Observer for subscriptions", "Subscriber interface for different consumers", "Thread-safe queue per topic", "Diagram consistent"], "code": ["publish appends and notifies; consumers track offsets", "Thread safety (locks/concurrent queues)", "Slow subscriber doesn''t block others", "Retry/acknowledgement handling"], "twist": ["Add consumer groups where each message goes to one member", "A subscriber crashes mid-processing", "Messages must be replayable from an offset", "Add a dead-letter topic for poison messages"]}', 1, 11, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('meeting-scheduler', 'Meeting Room Scheduler', 'Medium', 'Book rooms for time slots without conflicts.', 'Design a meeting room scheduler for an office.

Employees book rooms for time slots, invite people and get notified. Rooms have capacities and equipment. Clarify the details.', '{"requirements": ["Book room for start/end with attendees", "No overlapping bookings; capacity check", "Find free rooms for a slot", "Cancel/update; notifications", "Recurring meetings in or out of scope"], "entities": ["Scheduler, Room, Meeting/Booking, Interval, Employee, Calendar, Notification"], "uml": ["Room selection strategy", "Observer for invites/updates", "Interval overlap logic encapsulated", "Diagram consistent"], "code": ["Overlap check correct for edge cases (end == start)", "Atomic booking under concurrency", "Find available rooms efficiently", "Clean separation"], "twist": ["Add recurring weekly meetings", "Two people grab the same room at the same second", "Auto-release rooms if nobody checks in within 10 minutes", "Suggest the best room by attendee count and equipment"]}', 1, 12, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('digital-wallet', 'Digital Wallet (Paytm)', 'Medium', 'Wallets, top-ups, transfers and transaction history.', 'Design a digital wallet like Paytm.

Users add money from a bank, pay merchants, transfer to friends and see their history. Discuss consistency carefully.', '{"requirements": ["Create wallet, top-up from bank/card", "Transfer user-to-user, pay merchant", "Transaction history and statements", "Limits (KYC-based)", "Refunds/reversals"], "entities": ["User, Wallet, Transaction (type, status), PaymentMethod, Merchant, Ledger entry"], "uml": ["Transaction types as hierarchy or Command", "Payment method Strategy", "Double-entry ledger idea", "Observer for notifications"], "code": ["transfer debits and credits atomically", "Idempotency key prevents double charge", "Balance never negative", "Limits enforced"], "twist": ["Same transfer request arrives twice due to a retry", "Add cashback offers", "Bank top-up succeeds but our callback is lost", "Freeze a wallet suspected of fraud"]}', 1, 14, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('shopping-cart', 'Shopping Cart & Checkout (Amazon)', 'Medium', 'Cart, inventory, coupons, checkout and orders.', 'Design the cart and checkout flow of an e-commerce site like Amazon.

Users add products to a cart, apply coupons, and check out to create an order. Inventory is limited. Scope it with the interviewer.', '{"requirements": ["Add/remove/update quantities", "Price calculation with discounts/coupons and tax", "Inventory check and reservation at checkout", "Order creation and payment", "Guest vs logged-in carts"], "entities": ["User, Product, Cart, CartItem, Inventory, Coupon/Discount, Order, OrderItem, Payment"], "uml": ["Discount rules as Strategy/Chain", "Order state machine", "Inventory behind an interface", "Diagram consistent"], "code": ["Total computed via composable rules", "Checkout reserves stock atomically", "Order created only after payment success or with compensation", "No god class"], "twist": ["Two users check out the last unit at once", "Stack two coupons with rules on which combine", "Price changes while the item sits in the cart", "Split one order across two warehouses"]}', 1, 15, 'lld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('unique-id-generator', 'Unique ID Generator', 'Easy', 'Generate unique, roughly sortable IDs across many servers.', 'Design a service that generates unique IDs for a distributed system, like Twitter''s Snowflake.

IDs must be unique across many servers and ideally sortable by time. Clarify requirements first.', '{"requirements": ["Uniqueness across servers and restarts", "Sortable by time? numeric? size (64-bit)", "Throughput needed", "No single point of failure"], "estimation": ["IDs per second per node and total", "Bits needed for timestamp, machine id, sequence", "How many years the timestamp lasts"], "api": ["Library vs service API (GET /id or in-process)", "Layout: timestamp | datacenter | machine | sequence"], "architecture": ["Options compared: UUID, DB auto-increment, ticket server, Snowflake", "Machine id assignment (config/ZooKeeper)", "Diagram of generators per node"], "deepdive": ["Clock skew and clocks going backwards", "Sequence overflow within a millisecond", "Trade-offs: UUID size vs sortability", "Failure of coordination service"], "twist": ["IDs must be strictly increasing across all servers", "Support 10x traffic", "A server''s clock jumps back 2 seconds", "IDs must not reveal how many users we have"]}', 1, 1, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('leaderboard', 'Real-time Leaderboard', 'Easy', 'Top-K players and rank lookup for a live game.', 'Design a real-time leaderboard for a mobile game.

Players earn points; everyone sees the top 10 and their own rank, updated in near real time. Clarify the scale.', '{"requirements": ["Update score, show top K, show my rank", "Global vs per-region/daily boards", "Real-time freshness", "Ties handling"], "estimation": ["DAU and score updates per second", "Number of players on a board", "Memory for a sorted set"], "api": ["POST /scores, GET /leaderboard/top?k=, GET /leaderboard/rank/{user}", "Storage choice: Redis sorted sets justified; durable store for history"], "architecture": ["Game servers -> score service -> Redis ZSET", "Persistent DB for scores/history", "Cache/read path for top K"], "deepdive": ["Scaling sorted sets: sharding by score range or approximate ranks", "Daily/weekly resets", "Durability if Redis fails", "Cheating/validation of score updates"], "twist": ["100M players on one global board", "Add friends-only leaderboards", "Redis node crashes", "Show rank changes live to watching users"]}', 1, 2, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('distributed-rate-limiter', 'Distributed Rate Limiter', 'Medium', 'Limit requests per user across many API servers.', 'Design a rate limiter used by an API gateway in front of many servers.

Each user or API key gets a limit, like 100 requests per minute. Clarify the rules.', '{"requirements": ["Limit by user/IP/API key; different tiers", "Algorithm choice open (token bucket, sliding window)", "Response when limited (429 + headers)", "Low latency overhead"], "estimation": ["Total QPS through the gateway", "Number of keys tracked; memory per key"], "api": ["Middleware/gateway API, config for rules", "Headers: X-RateLimit-Remaining etc.", "Counter storage (Redis) with TTLs"], "architecture": ["Gateway with limiter middleware -> Redis cluster", "Rules service/config", "Fail-open vs fail-closed decision"], "deepdive": ["Algorithms compared: fixed window, sliding log, sliding window counter, token bucket", "Race conditions: atomic Lua/INCR", "Multi-region consistency", "Hot keys"], "twist": ["Limits must hold across 3 regions", "Redis is down: do we block everyone?", "Add per-endpoint limits", "A single customer sends 1M requests in a burst"]}', 1, 3, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('typeahead', 'Search Autocomplete (Typeahead)', 'Medium', 'Suggest top queries as the user types.', 'Design search autocomplete like Google''s suggestions.

As the user types, show the top 5 suggestions for the prefix within milliseconds. Clarify ranking and freshness.', '{"requirements": ["Top K suggestions per prefix", "Latency target (<100ms)", "Ranking by popularity; freshness", "Languages, personalisation in or out"], "estimation": ["Queries/day and keystroke QPS", "Number of unique queries; trie size"], "api": ["GET /suggest?q=prefix", "Data model: trie or prefix -> top K table"], "architecture": ["Suggestion service with in-memory trie", "Offline pipeline aggregating query logs", "CDN/browser caching of popular prefixes"], "deepdive": ["Precomputing top K at each node", "Sharding the trie by prefix", "Updating counts (batch vs streaming)", "Filtering offensive terms"], "twist": ["Trending queries must appear within minutes", "Support Hindi and Hinglish", "Personalise suggestions per user", "Cut infra cost by half"]}', 1, 4, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('web-crawler', 'Web Crawler', 'Medium', 'Crawl billions of pages politely and efficiently.', 'Design a web crawler for a search engine.

Starting from seed URLs, fetch pages, extract links and keep crawling, at the scale of billions of pages. Clarify scope.', '{"requirements": ["Scale (pages/month), content types", "Politeness (robots.txt, per-host rate)", "Freshness/recrawl", "Deduplication"], "estimation": ["Pages per second", "Storage for pages over time", "Bandwidth"], "api": ["URL frontier interface; fetcher; parser", "Storage: content store, URL-seen set"], "architecture": ["Frontier (priority + per-host queues) -> fetchers -> DNS cache -> parser -> link extractor -> frontier", "Content dedup and storage"], "deepdive": ["Politeness via per-host queues", "URL dedup with Bloom filters", "Content dedup (checksums/simhash)", "Traps, failures, distributed coordination"], "twist": ["Prioritise news sites for freshness", "A site serves infinite calendar pages", "Crawl JavaScript-heavy sites", "Cut crawl cost while keeping quality"]}', 1, 5, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('hotel-reservation', 'Hotel Reservation (Booking.com)', 'Medium', 'Search availability and book rooms without overbooking.', 'Design a hotel reservation platform like Booking.com or MakeMyTrip.

Users search hotels by city and dates, see availability and prices, and book. Many users target the same hotels in peak season.', '{"requirements": ["Search by city/dates/guests, view prices", "Reserve, pay, cancel", "No overbooking; inventory per room type per date", "Hotel admins update rates"], "estimation": ["Hotels, rooms, searches/sec, bookings/sec", "Read:write ratio"], "api": ["Search API, reservation API with idempotency key", "Tables: hotel, room_type, inventory(date, total, reserved), reservation", "SQL justified for transactions"], "architecture": ["Search service with cache/search index", "Reservation service with transactional DB", "Payment integration", "Walkthrough of a booking"], "deepdive": ["Concurrency: optimistic locking or DB constraints", "Caching availability safely", "Sharding by hotel", "Idempotent payments"], "twist": ["Allow 10% overbooking like airlines", "Flash sale on New Year''s Eve", "Payment succeeds but reservation write fails", "Add dynamic pricing"]}', 1, 9, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('metrics-monitoring', 'Metrics Monitoring & Alerting', 'Medium', 'Collect metrics from servers, store time series and alert.', 'Design a metrics monitoring and alerting system like Datadog or Prometheus.

Thousands of servers send metrics; engineers view dashboards and get alerts when things break.', '{"requirements": ["Ingest metrics (counters, gauges)", "Query for dashboards over time ranges", "Alert rules and notifications", "Retention and downsampling"], "estimation": ["Servers x metrics x frequency = data points/sec", "Storage per day with retention"], "api": ["Push or pull ingestion API", "Time-series data model (metric, tags, timestamp, value)", "TSDB choice justified"], "architecture": ["Agents -> collectors -> Kafka -> TSDB", "Query service for dashboards", "Alert evaluator -> notification service"], "deepdive": ["Downsampling and retention tiers", "High-cardinality tags problem", "Alert dedup and flapping", "Monitoring the monitor"], "twist": ["Cardinality explodes after a deploy", "Alert within 10 seconds of an outage", "Keep 1 year of data cheaply", "Add anomaly detection"]}', 1, 10, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('job-scheduler', 'Distributed Job Scheduler', 'Medium', 'Run millions of scheduled and recurring jobs reliably.', 'Design a distributed job scheduler, like cron at company scale.

Teams schedule one-off and recurring jobs; the system runs each on time, exactly once, with retries.', '{"requirements": ["One-off and cron-style jobs", "Run on time, retries, timeouts", "Exactly-once vs at-least-once", "Job status and history"], "estimation": ["Jobs scheduled, executions per second at peak", "Storage for job definitions and runs"], "api": ["Create/update/cancel job APIs", "Tables: jobs, executions; index on next_run_time"], "architecture": ["Scheduler polls due jobs -> queue -> workers", "Leader election/partitioning of schedulers", "Status store"], "deepdive": ["Avoid double execution (locks/leases)", "Partitioning due jobs", "Worker failure and retries with backoff", "Thundering herd at midnight"], "twist": ["10 million jobs all scheduled for 00:00", "A worker dies halfway through a job", "Jobs depend on other jobs (DAGs)", "Let teams set priorities"]}', 1, 11, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('distributed-cache', 'Distributed Cache / Key-Value Store', 'Hard', 'A Redis- or DynamoDB-like store that scales horizontally.', 'Design a distributed key-value store or cache.

Clients get and put values by key with very low latency; the system spans many nodes and survives failures.', '{"requirements": ["get/put/delete; value size limits", "Cache (TTL, eviction) vs durable store", "Consistency requirements", "Availability and latency targets"], "estimation": ["Total data size, QPS", "Nodes needed by memory and throughput"], "api": ["get(key), put(key, value, ttl) API", "Partitioning scheme"], "architecture": ["Clients -> nodes with consistent hashing", "Replication factor", "Gossip/membership"], "deepdive": ["Consistent hashing with virtual nodes", "Replication and quorum (N, R, W)", "Conflict resolution (versioning)", "Failure detection, hinted handoff, rebalancing"], "twist": ["A node holding hot keys melts", "Strong consistency for some keys", "Add cross-region replication", "Rebalance with zero downtime"]}', 1, 12, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('event-ticketing', 'Ticket Booking at Scale (BookMyShow)', 'Hard', 'Sell seats for a huge concert without overselling.', 'Design ticket booking for a massive event, like a Coldplay concert on BookMyShow.

Millions of users try to book a few thousand seats the moment sales open. Seats must never be sold twice.', '{"requirements": ["Browse events, seat map, hold seats, pay", "Hold timeout", "No double selling", "Fairness under huge spikes"], "estimation": ["Concurrent users at sale start", "Seats and booking QPS"], "api": ["Hold seats API with expiry, confirm API", "Seat inventory model and status"], "architecture": ["Virtual waiting room/queue", "Booking service with seat locks", "Payment service", "Walkthrough of a booking"], "deepdive": ["Seat locking (Redis with TTL or DB row locks)", "Waiting room to shed load", "Idempotency and payment race", "Caching seat map vs freshness"], "twist": ["Bots buy all tickets in 3 seconds", "Payment gateway slows to 30 seconds", "Release unpaid holds instantly", "Add resale of tickets"]}', 1, 13, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('payment-system', 'Payment System', 'Hard', 'Process payments reliably with exactly-once semantics.', 'Design a payment system for an e-commerce company, like the backend behind Razorpay checkout.

Orders are paid through external payment providers; money must never be lost or charged twice.', '{"requirements": ["Pay-in flow, refunds", "Integrate external PSPs", "Exactly-once charge, reconciliation", "Payment status visible to users"], "estimation": ["Transactions per day and per second at peak", "Storage for ledger"], "api": ["POST /payments with idempotency key; webhooks from PSP", "Tables: payment, ledger entries (double-entry), outbox"], "architecture": ["Payment service -> PSP; webhook handler; ledger; wallet", "Reconciliation job", "Walkthrough"], "deepdive": ["Idempotency keys and retries", "Distributed transactions: saga/outbox", "Reconciliation with PSP reports", "Handling PSP timeouts (unknown state)"], "twist": ["PSP charged the user but our service crashed", "Add a second PSP with failover", "Support partial refunds", "Settle money to sellers daily"]}', 1, 14, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('cloud-storage', 'Cloud File Storage (Google Drive)', 'Hard', 'Upload, sync and share files across devices.', 'Design a cloud file storage service like Google Drive or Dropbox.

Users upload files, sync them across devices, and share with others. Files can be large.', '{"requirements": ["Upload/download, sync across devices", "Sharing and permissions", "Versioning", "Large files, resumable uploads"], "estimation": ["Users, storage per user, uploads/day", "Total storage and bandwidth"], "api": ["Upload (chunked, resumable), download, list, share APIs", "Metadata tables: files, chunks, versions, permissions"], "architecture": ["Clients -> API -> metadata DB; blocks in object storage", "Sync/notification service", "CDN for downloads"], "deepdive": ["Chunking and dedup", "Sync conflicts", "Metadata consistency", "Notifying devices of changes (long polling/websockets)"], "twist": ["Two devices edit the same file offline", "Cut storage cost with dedup", "A 50 GB upload on a flaky connection", "Add link sharing with expiry"]}', 1, 15, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('food-delivery-platform', 'Food Delivery Platform (Swiggy)', 'Hard', 'Orders, restaurants and real-time delivery at city scale.', 'Design the backend of a food delivery platform like Swiggy or Zomato.

Customers order from restaurants; delivery partners are assigned and tracked live until delivery.', '{"requirements": ["Browse/search restaurants, order, pay", "Restaurant order handling", "Partner assignment and live tracking", "ETAs and notifications"], "estimation": ["Orders per day, peak orders/sec (dinner)", "Partner location updates/sec"], "api": ["Order APIs, restaurant APIs, partner location updates", "Tables: orders, order_items, restaurants, partners"], "architecture": ["Search service, order service, dispatch service, location service, notification", "Event bus between services"], "deepdive": ["Dispatch algorithm and geo indexing", "Order state machine across services (saga)", "Peak scaling", "Consistency of menu availability"], "twist": ["Heavy rain doubles orders in 20 minutes", "Batch two orders on one partner", "Restaurant goes offline after accepting", "Add grocery delivery"]}', 1, 18, 'hld', strftime('%s','now'));
INSERT OR IGNORE INTO problems (slug, title, difficulty, summary, statement, rubric, published, position, track, updated_at) VALUES ('collaborative-editor', 'Collaborative Editor (Google Docs)', 'Hard', 'Many people editing the same document live.', 'Design a collaborative document editor like Google Docs.

Multiple users edit the same document at once and see each other''s changes and cursors in real time.', '{"requirements": ["Real-time concurrent editing", "Cursors/presence", "Version history", "Offline edits and sync"], "estimation": ["Concurrent editors per doc, ops per second", "Storage for docs and history"], "api": ["WebSocket ops protocol", "Data model: document snapshots + operation log"], "architecture": ["Clients -> collaboration servers (doc sessions) -> op log/storage", "Presence service"], "deepdive": ["OT vs CRDT trade-offs", "Routing all editors of a doc to one server", "Snapshots + op log compaction", "Handling reconnects"], "twist": ["500 people edit the same doc", "A user edits offline for 2 hours", "Add comments and suggestions", "Restore any past version"]}', 1, 19, 'hld', strftime('%s','now'));

